// Generated by scripts/book-pack/import.mjs from the private book pack, then finished by hand.
// Section creating_trust: structure labels are the book's short names; every other word is the
// pack's own-words coaching or ours. No quotation from the book. Corporate Culture is a variant of
// Decision Maker's Maslow pyramids: the book's picture is a parody, perks stacked on top of the
// conditions they cannot replace, so the pyramid here has the conditions at its base and makes no
// claim about psychology. The Trust Triangle is a list of three, never a pick-two triangle: the
// book needs all three corners at once.
import { listTool, pathTool, quadrantTool } from '../../decision-book/families/index.mjs';
import { OWN_PART_STEP, step } from './shared.mjs';

// Decision Maker's Maslow pyramids rank needs; the book's version mocks a ranking of perks. The
// base is the working conditions and the top the perks, and the point is that the base comes
// first. The classic needs and wants stay in dm_maslow.
